// Grade 2 passages (validated by live-patches/grade-journey/validate.mjs). Built by validate.mjs --write.
export const PASSAGES = [{"id":"g2-u1-p01","unit":"G2-U1","pool":"practice","title":"The Picnic Basket","genre":"narrative","source":"app-original","license":"app-original","text":"Sam and his sister Meg had a picnic plan. Mom packed a big basket. In it she put six muffins, two apples and a jug of lemon water.\n\nThe kids went to the park. They sat on a red blanket under a tall tree. Meg set out the napkins. Sam set out the muffins.\n\nThen a little rabbit hopped up. It sat still and looked at the basket. Its nose went up and down.\n\n\"I think the rabbit is hungry,\" said Meg.\n\nSam had a carrot in his pocket. He set it on the grass. The rabbit hopped to the carrot. It ate the carrot with a crunch, crunch, crunch. Then it hopped back into the bushes.\n\n\"That rabbit had a picnic too!\" said Sam. The kids smiled and ate the muffins until sunset.","questions":[{"type":"literal","q":"What did Mom pack the food in?","options":["a big basket","a red box","a paper bag"],"answer":0,"evidence":"Mom packed a big basket."},{"type":"literal","q":"Where did Sam keep a carrot?","options":["in the basket","in his pocket","in his hat"],"answer":1,"evidence":"Sam had a carrot in his pocket."},{"type":"inference","q":"Why did Meg think the rabbit was hungry?","options":["It ran up the tall tree.","It sat on a red napkin.","It looked at the basket."],"answer":2},{"type":"sequence","q":"What did the rabbit do last?","options":["ate a muffin from the basket","sat down on the red blanket","hopped back into the bushes"],"answer":2,"evidence":"Then it hopped back into the bushes."}],"grade":2,"words":134,"auto":{"fk":1.3,"decodable":1,"checks":"pass"}},{"id":"g2-u1-p02","unit":"G2-U1","pool":"practice","title":"A Kitten Named Button","genre":"narrative","source":"app-original","license":"app-original","text":"Rosa got a kitten for her birthday. The kitten was gray with a white chin. It had a tiny pink nose, as round as a button.\n\n\"I will name her Button,\" said Rosa.\n\nButton liked to play. She ran after a ribbon. She jumped into a paper bag. She hid in Rosa's slipper and peeked out.\n\nAt dinner, Button was missing. Rosa looked under the table. She looked in the basket of yarn. She looked behind the curtain. No kitten!\n\nThen Rosa heard a little sound. \"Mew, mew.\" It came from the sink.\n\nButton was sitting in a dish of water. Her fur was wet and her tail was dripping.\n\nRosa picked her up and dried her with a soft towel. Button started to purr. Then she fell asleep on Rosa's lap, as snug as a muffin in a pan.","questions":[{"type":"literal","q":"Why did Rosa name the kitten Button?","options":["It had a button on its tail.","It liked to play with buttons.","Its nose was as round as a button."],"answer":2,"evidence":"It had a tiny pink nose, as round as a button."},{"type":"sequence","q":"Where did Rosa look first for Button?","options":["in the yarn basket","under the table","behind the curtain"],"answer":1,"evidence":"Rosa looked under the table."},{"type":"literal","q":"Where was Button?","options":["in a paper bag","in the sink","in a slipper"],"answer":1,"evidence":"It came from the sink."},{"type":"inference","q":"How did Button feel at the end?","options":["happy and warm","hungry and sad","upset and cold"],"answer":0}],"grade":2,"words":140,"auto":{"fk":1.9,"decodable":0.99,"checks":"pass"}},{"id":"g2-u1-c01","unit":"G2-U1","pool":"check","title":"The Garden Helper","genre":"narrative","source":"app-original","license":"app-original","text":"Grandpa Leon has a garden behind his house. It has carrots, peppers and a big pumpkin patch. Kofi likes to help him on Sundays.\n\nOne Sunday, Kofi saw a problem. Something was nibbling the lettuce. Little bits of the green leaves were missing.\n\n\"Who is the robber?\" said Kofi. He sat very still by the fence and waited.\n\nThen a small brown rabbit hopped under the fence. It began to munch on the lettuce.\n\n\"So you are the robber!\" said Kofi with a grin. The rabbit ran back under the fence.\n\nGrandpa had a plan. He and Kofi put up a better fence with wire. Then they made a little garden just for the rabbit. They planted clover and lettuce in it, on the far side of the fence.\n\nThe next Sunday, the rabbit was munching in its own garden. Grandpa's lettuce was safe.\n\n\"Now we have two gardens,\" said Kofi, \"and one happy rabbit.\"","questions":[{"type":"literal","q":"When does Kofi help Grandpa?","options":["on Sundays","on Mondays","after dinner"],"answer":0,"evidence":"Kofi likes to help him on Sundays."},{"type":"literal","q":"What was getting eaten in the garden?","options":["the peppers","the lettuce","the pumpkins"],"answer":1,"evidence":"Something was nibbling the lettuce."},{"type":"sequence","q":"What did Kofi do before the rabbit came?","options":["planted clover by the back gate","put up a new fence with wire","sat still by the fence and waited"],"answer":2,"evidence":"He sat very still by the fence and waited."},{"type":"evidence","q":"Which sentence best shows the plan worked?","options":["Grandpa's lettuce was safe.","Grandpa had a plan.","It began to munch on the lettuce."],"answer":0,"evidence":"Grandpa's lettuce was safe."},{"type":"main","q":"What is this story mostly about?","options":["how a rabbit got lost on a farm","how Kofi and Grandpa kept a rabbit out","how to grow a big pumpkin in a garden"],"answer":1}],"grade":2,"words":155,"auto":{"fk":2.6,"decodable":1,"checks":"pass"}},{"id":"g2-u1-c02","unit":"G2-U1","pool":"check","title":"Rocket Day","genre":"narrative","source":"app-original","license":"app-original","text":"It was Rocket Day at Maple Street School. Every kid in Mister Tran's class made a rocket.\n\nAva had a paper tube, a plastic cup and some tape. She cut three fins from paper and taped them to the bottom. She put the cup on top for a nose. Then she painted it silver and purple.\n\n\"My rocket is the Comet,\" said Ava.\n\nHer pal Ben made a rocket too. His was red and yellow. He named it the Dragon.\n\nAt the end of the day, the class went out to the playground. Mister Tran had a launcher. You set a rocket on it and then you stomp on a pump. The air shoots the rocket up!\n\nBen went first. The Dragon went up and landed in the sandbox. Then it was Ava's turn. She stomped as hard as she could. The Comet zoomed up, up, up, past the top of the swings!\n\nAva clapped. Ben clapped too. \"Let's make a bigger one next time,\" he said.","questions":[{"type":"literal","q":"What did Ava put on top for a nose?","options":["the tube","the tape","the cup"],"answer":2,"evidence":"She put the cup on top for a nose."},{"type":"literal","q":"What did Ben name his rocket?","options":["the Dragon","the Comet","the Planet"],"answer":0,"evidence":"He named it the Dragon."},{"type":"why","q":"How did the rockets go up?","options":["The wind lifted them up.","A pump shot air into them.","The kids threw them up."],"answer":1},{"type":"sequence","q":"Where did the Dragon land?","options":["on the swings","in the garden","in the sandbox"],"answer":2,"evidence":"The Dragon went up and landed in the sandbox."},{"type":"inference","q":"How did Ben feel about the Comet?","options":["He was happy for Ava.","He was upset with Ava.","He did not see it at all."],"answer":0}],"grade":2,"words":167,"auto":{"fk":1.1,"decodable":0.99,"checks":"pass"}},{"id":"g2-u1-c03","unit":"G2-U1","pool":"check","title":"Baby Sea Turtles","genre":"informational","source":"app-original","license":"app-original","text":"Sea turtles spend most of their lives in the sea. But a mother sea turtle comes up on the sand to lay her eggs.\n\nShe crawls up the beach at night. With her back flippers, she digs a hole in the sand. She lays about one hundred eggs in it. The eggs are white and round, a little like ping pong balls. Then she covers the hole with sand and swims back to the sea.\n\nThe sun keeps the sand warm. After about two months, the eggs hatch. The baby turtles dig up to the top of the sand. Most of them come out at night, when it is cooler.\n\nThen the babies race to the water. They follow the light of the moon on the waves. It is a long trip for a tiny turtle!\n\nSome people help the turtles. They keep the beach dark at night, so the babies do not get lost.","caption":"A baby sea turtle is about as big as a cookie.","questions":[{"type":"literal","q":"Where does a mother sea turtle lay her eggs?","options":["in a nest in a tree","in a hole in the sand","on a rock in the sea"],"answer":1,"evidence":"With her back flippers, she digs a hole in the sand."},{"type":"literal","q":"How long do the eggs take to hatch?","options":["about two days","about one year","about two months"],"answer":2,"evidence":"After about two months, the eggs hatch."},{"type":"sequence","q":"What do the babies do after they dig out?","options":["race to the water","lay their eggs","sleep in the sand"],"answer":0,"evidence":"Then the babies race to the water."},{"type":"why","q":"Why do people keep the beach dark at night?","options":["so the mother can sleep well","so the babies do not get lost","so the eggs can stay warm"],"answer":1},{"type":"main","q":"What is this text mostly about?","options":["what grown sea turtles like to eat","how people can swim in the sea","how baby sea turtles get to the sea"],"answer":2}],"grade":2,"words":155,"auto":{"fk":1.7,"decodable":0.99,"checks":"pass"}},{"id":"g2-u1-c04","unit":"G2-U1","pool":"check","title":"Pancake Sunday","genre":"narrative","source":"app-original","license":"app-original","text":"On Sunday morning, Lily and her dad made pancakes.\n\nFirst, Dad got out a big bowl. Lily cracked two eggs into it. Then she added milk and flour. Dad let her mix it with a whisk until it was smooth. The batter was thick and yellow.\n\nDad put a pan on the stove. He added a little butter. It went sizzle, sizzle in the hot pan.\n\n\"Now we wait for the bubbles,\" said Dad. Little bubbles popped up on top of the pancake. Then Dad flipped it over. It was golden brown!\n\nLily wanted to flip one too. Dad helped her hold the pan. She flipped it up, and it landed on the stove!\n\nLily was upset. But Dad just smiled. \"That one is a practice pancake,\" he said.\n\nLily tried again. This time the pancake landed back in the pan. They made ten pancakes and ate them with lemon and honey.","questions":[{"type":"literal","q":"What did Lily crack into the bowl?","options":["two eggs","six eggs","a lemon"],"answer":0,"evidence":"Lily cracked two eggs into it."},{"type":"literal","q":"What did Dad wait for before flipping?","options":["smoke","bubbles","butter"],"answer":1,"evidence":"\"Now we wait for the bubbles,\" said Dad."},{"type":"literal","q":"Where did Lily's first pancake land?","options":["on the table","on her plate","on the stove"],"answer":2,"evidence":"She flipped it up, and it landed on the stove!"},{"type":"evidence","q":"Which sentence best shows that Dad stayed calm?","options":["But Dad just smiled.","Lily was upset.","Lily tried again."],"answer":0,"evidence":"But Dad just smiled."},{"type":"theme","q":"What lesson does Lily learn?","options":["Pancakes are best with jam.","It is okay to try again.","Only grown-ups can cook."],"answer":1}],"grade":2,"words":152,"auto":{"fk":1.2,"decodable":0.99,"checks":"pass"}},{"id":"g2-u2-p01","unit":"G2-U2","pool":"practice","title":"The Lion and the Mouse","genre":"narrative","source":"app-original","license":"app-original","text":"A big lion was sleeping in the warm afternoon sun. A little mouse ran across his nose by mistake. The lion woke up with a growl and trapped the mouse under his heavy paw.\n\n\"Please let me go,\" said the mouse. \"One day I may help you.\"\n\nThe lion smiled. \"How can a tiny mouse help a big lion?\" he said. But he let the mouse go.\n\nA few days later, the lion was caught in a hunter's net. He pulled and twisted, but he could not get free. He roared so loudly that the whole forest heard him.\n\nThe little mouse remembered her promise. She hurried to the net as fast as she could. She chewed the ropes with her sharp teeth. Snip, snip, snip! Soon there was a big hole in the net. The lion stepped out. He was free!\n\n\"Thank you, little friend,\" said the lion. \"I was wrong. A small friend can be a big help.\"\n\nLesson: Be kind to others, even small ones. They may help you one day.","questions":[{"type":"literal","q":"Why did the lion wake up?","options":["The sun was too hot.","A mouse ran across his nose.","A hunter made a loud sound."],"answer":1,"evidence":"A little mouse ran across his nose by mistake."},{"type":"sequence","q":"What happened after the lion let the mouse go?","options":["He ate a big lunch.","He fell asleep in the shade.","He was caught in a net."],"answer":2,"evidence":"A few days later, the lion was caught in a hunter's net."},{"type":"literal","q":"How did the mouse get the lion out?","options":["She chewed the ropes.","She called the hunter.","She dug a deep hole."],"answer":0,"evidence":"She chewed the ropes with her sharp teeth."},{"type":"theme","q":"What is the lesson of this fable?","options":["Never take a nap in the hot sun.","Small friends can be a big help.","Lions are the best hunters of all."],"answer":1}],"grade":2,"words":174,"auto":{"fk":0.7,"decodable":null,"checks":"pass"}},{"id":"g2-u2-p02","unit":"G2-U2","pool":"practice","title":"The Fox and the Grapes","genre":"narrative","source":"app-original","license":"app-original","text":"One hot day, a fox was walking down a path. He was very hungry. Then he saw a vine with purple grapes. The grapes hung high up on a tree branch. They looked sweet and juicy.\n\n\"Those grapes are just what I need,\" said the fox.\n\nHe jumped up to get them. He missed. He backed up and ran and jumped again. He missed again! He tried and tried, but the grapes were too high.\n\nAt last, the fox was hot and tired. He sat down and looked up at the grapes. Then he put his nose in the air.\n\n\"I did not want those grapes,\" he said. \"I am sure they are sour.\"\n\nAnd he walked away with his tummy still empty.\n\nLesson: Some people say they did not want a thing when they cannot get it.","questions":[{"type":"literal","q":"Where were the grapes?","options":["high up on a tree branch","on the path by the fox","in a basket on a table"],"answer":0,"evidence":"The grapes hung high up on a tree branch."},{"type":"sequence","q":"What did the fox do when he first saw the grapes?","options":["He asked a bird for help.","He jumped up to get them.","He walked away from them."],"answer":1,"evidence":"He jumped up to get them."},{"type":"inference","q":"Why did the fox say the grapes were sour?","options":["He had tasted them.","A friend told him so.","He could not get them."],"answer":2},{"type":"theme","q":"What lesson does this fable teach?","options":["People pretend not to want what they cannot get.","Foxes are the best jumpers in all of the woods.","Always eat sweet grapes on a very hot day."],"answer":0}],"grade":2,"words":138,"auto":{"fk":0.3,"decodable":null,"checks":"pass"}},{"id":"g2-u2-c01","unit":"G2-U2","pool":"check","title":"The Tortoise and the Hare","genre":"narrative","source":"app-original","license":"app-original","text":"Hare was the fastest animal in the woods, and he liked to brag about it. \"Nobody can beat me,\" he said.\n\nTortoise was slow, but he was tired of the bragging. \"I will race you,\" he said.\n\nHare laughed so hard he fell over. \"You? You are the slowest one of all!\" But the race was set for the next day.\n\nThe animals lined up to watch. \"Go!\" called Owl. Hare zoomed off. Soon Tortoise was far behind.\n\nHare looked back. He could not even see Tortoise. \"I have lots of time,\" he said. \"I will take a nap.\" He lay down under a shady tree and fell fast asleep.\n\nTortoise kept going, one slow step at a time. He did not stop. He passed the sleeping Hare.\n\nWhen Hare woke up, he ran as fast as he could. But it was too late. Tortoise was crossing the finish line! All the animals cheered.\n\nLesson: Slow and steady wins the race.","questions":[{"type":"literal","q":"What did Hare like to do?","options":["sing with Owl","help the others","brag about it"],"answer":2,"evidence":"Hare was the fastest animal in the woods, and he liked to brag about it."},{"type":"why","q":"Why did Hare take a nap?","options":["He thought he had lots of time.","He was sick and needed rest.","Owl told him to stop."],"answer":0},{"type":"sequence","q":"What did Tortoise do while Hare slept?","options":["He took a nap as well.","He passed the sleeping Hare.","He went home to eat lunch."],"answer":1,"evidence":"He passed the sleeping Hare."},{"type":"evidence","q":"Which sentence best shows how Tortoise won?","options":["Hare zoomed off.","The animals lined up to watch.","He did not stop."],"answer":2,"evidence":"He did not stop."},{"type":"theme","q":"What is the lesson of this fable?","options":["Slow and steady wins the race.","The fastest animal always wins.","Naps make you run faster."],"answer":0}],"grade":2,"words":161,"auto":{"fk":0.7,"decodable":null,"checks":"pass"}},{"id":"g2-u2-c02","unit":"G2-U2","pool":"check","title":"The Crow and the Jar","genre":"narrative","source":"app-original","license":"app-original","text":"It had not rained for many days. The ponds were dry, and a crow was very thirsty. She flew here and there, looking for a drink.\n\nAt last she saw a tall jar in a garden. She flew down and looked in. There was a little water at the bottom! But the jar was tall and thin. Her beak could not reach the water.\n\nThe crow did not give up. She looked around the garden. She saw a pile of small stones. That gave her an idea.\n\nShe picked up one stone in her beak and dropped it into the jar. Plunk! Then she dropped in another one. Plunk! With each stone, the water came up a little higher.\n\nThe crow kept working. Ten stones, twenty stones, thirty stones. At last the water was near the top of the jar. The crow took a long, cool drink.\n\nLesson: When you think hard and keep trying, you can solve a problem.","questions":[{"type":"literal","q":"What was the crow's problem at first?","options":["The water in the jar was too hot.","Her beak could not reach the water.","The jar had a heavy lid on top of it."],"answer":1,"evidence":"Her beak could not reach the water."},{"type":"sequence","q":"What did the crow do after she saw the stones?","options":["flew far away to find a pond","tipped the tall jar over","dropped them into the jar"],"answer":2,"evidence":"She picked up one stone in her beak and dropped it into the jar."},{"type":"why","q":"Why did the water come up?","options":["The stones filled the jar.","It began to rain hard.","The crow shook the jar."],"answer":0},{"type":"inference","q":"Which word best tells about the crow?","options":["grumpy","clever","lazy"],"answer":1},{"type":"theme","q":"What is the lesson of this fable?","options":["Crows do not like stones.","Never drink from a jar.","Think hard and keep trying."],"answer":2}],"grade":2,"words":160,"auto":{"fk":0.9,"decodable":null,"checks":"pass"}},{"id":"g2-u2-c03","unit":"G2-U2","pool":"check","title":"The Boy Who Cried Wolf","genre":"narrative","source":"app-original","license":"app-original","text":"A boy named Tomas had a job. Each day he took the sheep up the hill to eat grass. He had to keep them safe. If a wolf came, he would yell, and the people in the town would run to help.\n\nBut the hill was quiet, and Tomas was bored. One day he had an idea. \"Wolf! Wolf!\" he yelled. The people ran up the hill. But there was no wolf. Tomas giggled. The people were upset and went home.\n\nThe next day, Tomas did it again. \"Wolf! Wolf!\" The people ran up the hill. No wolf! They were even more upset this time.\n\nThen one evening, a real wolf came out of the trees. It crept up to the sheep. \"Wolf! Wolf!\" yelled Tomas. \"Please help!\"\n\nBut this time, no one came. \"It is just another trick,\" they said. The wolf chased the sheep away into the hills.\n\nLesson: If you tell lies, people will not trust you, even when you tell the truth.","questions":[{"type":"literal","q":"What did Tomas have to do for the sheep?","options":["keep them safe","sell them in town","give them baths"],"answer":0,"evidence":"He had to keep them safe."},{"type":"why","q":"Why did Tomas yell \"Wolf!\" the first time?","options":["He was lost.","He was bored.","He saw a wolf."],"answer":1},{"type":"sequence","q":"What happened when the real wolf came?","options":["The whole town ran.","The wolf ran off.","No one came."],"answer":2,"evidence":"But this time, no one came."},{"type":"inference","q":"How did Tomas most likely feel at the end?","options":["sorry and sad","proud and glad","sleepy and calm"],"answer":0},{"type":"theme","q":"What is the lesson of this fable?","options":["Wolves only come out at night.","Lies make people stop trusting you.","Sheep need to eat lots of grass."],"answer":1}],"grade":2,"words":166,"auto":{"fk":0.1,"decodable":null,"checks":"pass"}},{"id":"g2-u2-c04","unit":"G2-U2","pool":"check","title":"Stone Soup","genre":"narrative","source":"app-original","license":"app-original","text":"A tired traveler came to a small town. She was hungry, but she had no food. All she had was a big pot.\n\nShe asked the people for something to eat. \"We have nothing to share,\" they said, and shut their doors.\n\nSo the traveler filled her pot with water. She made a fire in the middle of the town. Then she dropped a smooth gray stone into the pot.\n\nA girl came by. \"What are you making?\" she asked.\n\n\"Stone soup,\" said the traveler. \"It is very good. But it would be better with a carrot.\"\n\n\"I have a carrot!\" said the girl. She ran home and got one.\n\nThen a man came by. He had an onion to add. A woman brought some beans. A boy brought a bag of potatoes. Soon everyone was adding something.\n\nThe soup bubbled and smelled wonderful. The whole town sat down and ate together. It was the best soup they ever had.\n\nLesson: When everyone shares a little, there is plenty for all.","questions":[{"type":"literal","q":"What did the traveler put in the pot first?","options":["a big orange carrot","a bag of potatoes","a smooth gray stone"],"answer":2,"evidence":"Then she dropped a smooth gray stone into the pot."},{"type":"literal","q":"What did the girl bring?","options":["a carrot","an onion","some beans"],"answer":0,"evidence":"\"I have a carrot!\""},{"type":"why","q":"Why did the people shut their doors at first?","options":["They were scared of the pot.","They did not want to share.","It was very late at night."],"answer":1},{"type":"evidence","q":"Which sentence best shows that people began to share?","options":["She was hungry, but she had no food.","A girl came by.","Soon everyone was adding something."],"answer":2,"evidence":"Soon everyone was adding something."},{"type":"theme","q":"What is the lesson of this folktale?","options":["Sharing makes plenty for everyone.","Stones make the best soup.","Never let a stranger in town."],"answer":0}],"grade":2,"words":171,"auto":{"fk":1.5,"decodable":null,"checks":"pass"}},{"id":"g2-u3-p01","unit":"G2-U3","pool":"practice","title":"How to Plant a Bean Seed","genre":"informational","source":"app-original","license":"app-original","text":"You can grow a bean plant at home! Here is what you need: a paper cup, some soil, a bean seed and water.\n\nStep 1: Poke a small hole in the bottom of the cup. This lets extra water drain out, so the roots do not get too wet.\n\nStep 2: Fill the cup with soil. Leave a little space at the top.\n\nStep 3: Push the bean seed into the soil with your finger. It should be about as deep as your first knuckle. Cover it up with soil.\n\nStep 4: Water the soil until it is damp, but not soggy.\n\nStep 5: Put the cup by a sunny window. Plants need light to grow.\n\nLast, check your cup every day. Add a little water when the soil feels dry. In about one week, a tiny green sprout will pop up. Soon it will have leaves!","caption":"What you need: cup, soil, bean seed, water","questions":[{"type":"sequence","q":"What do you do first?","options":["Push the seed into the soil.","Put the cup by a window.","Poke a hole in the cup."],"answer":2,"evidence":"Step 1: Poke a small hole in the bottom of the cup."},{"type":"why","q":"Why do you poke a hole in the cup?","options":["so extra water can drain out","so the sun can get in","so bugs can crawl inside"],"answer":0},{"type":"literal","q":"Where should you put the cup?","options":["in the cold fridge","by a sunny window","in a dark closet"],"answer":1,"evidence":"Step 5: Put the cup by a sunny window."},{"type":"literal","q":"When will a sprout pop up?","options":["in about one hour","in about one year","in about one week"],"answer":2,"evidence":"In about one week, a tiny green sprout will pop up."}],"grade":2,"words":147,"auto":{"fk":1.2,"decodable":null,"checks":"pass"}},{"id":"g2-u3-p02","unit":"G2-U3","pool":"practice","title":"How to Wash Your Hands","genre":"informational","source":"app-original","license":"app-original","text":"Germs are tiny living things that can make you sick. They are so small that you cannot see them. Washing your hands is one of the best ways to get rid of them.\n\nFirst, wet your hands with clean water. Then turn off the tap to save water.\n\nNext, put soap on your hands. Rub them together to make lots of bubbles.\n\nThen scrub every part of your hands. Scrub the backs, between your fingers and under your nails. Keep scrubbing for at least twenty seconds. That is about as long as it takes to sing \"Happy Birthday\" two times.\n\nAfter that, rinse your hands under clean water. Watch the bubbles wash away.\n\nLast, dry your hands with a clean towel.\n\nWhen should you wash your hands? Wash them before you eat, after you use the bathroom and after you play outside. Clean hands help keep you and your friends healthy!","caption":"Scrub for 20 seconds: sing \"Happy Birthday\" two times.","questions":[{"type":"sequence","q":"What do you do right after you wet your hands?","options":["Sing a song.","Turn off the tap.","Dry them with a towel."],"answer":1,"evidence":"Then turn off the tap to save water."},{"type":"literal","q":"How long should you scrub?","options":["at least two minutes","about five seconds","at least twenty seconds"],"answer":2,"evidence":"Keep scrubbing for at least twenty seconds."},{"type":"sequence","q":"What is the last step?","options":["Dry your hands with a towel.","Rinse the soap off your hands.","Scrub under all your nails."],"answer":0,"evidence":"Last, dry your hands with a clean towel."},{"type":"author","q":"Why did the author write this?","options":["to sell a new kind of soap","to teach how to wash hands","to tell a story about germs"],"answer":1}],"grade":2,"words":151,"auto":{"fk":2.2,"decodable":null,"checks":"pass"}},{"id":"g2-u3-c01","unit":"G2-U3","pool":"check","title":"How to Make a Pinecone Bird Feeder","genre":"informational","source":"app-original","license":"app-original","text":"Birds need extra food in winter, when it is hard to find seeds. You can make a feeder to help them.\n\nYou will need a pinecone, a piece of string, a spoon, some sunflower seed butter and a plate of birdseed.\n\nFirst, tie the string around the top of the pinecone. Make a loop at the end so you can hang it up later.\n\nNext, use the spoon to spread seed butter all over the pinecone. Push it into the gaps between the scales. The butter is sticky, so it will hold the seeds.\n\nThen roll the pinecone in the plate of birdseed. Press it down so lots of seeds stick on.\n\nLast, hang your feeder from a tree branch. Pick a spot you can see from a window.\n\nNow wait and watch. Soon birds will come to eat. Count how many birds visit each day. Which kinds can you name?","caption":"You will need: pinecone, string, spoon, seed butter, birdseed","questions":[{"type":"sequence","q":"What do you do first?","options":["Tie string on the pinecone.","Roll it in the birdseed.","Hang it from a tree branch."],"answer":0,"evidence":"First, tie the string around the top of the pinecone."},{"type":"why","q":"Why do you spread seed butter on the pinecone?","options":["Birds like to drink it.","It is sticky, so seeds stay on.","It keeps the pinecone warm."],"answer":1},{"type":"sequence","q":"What comes after you spread the butter?","options":["Make a loop in the string.","Count the birds that visit.","Roll the pinecone in birdseed."],"answer":2,"evidence":"Then roll the pinecone in the plate of birdseed."},{"type":"literal","q":"Where should you hang the feeder?","options":["from a tree branch","from the front door","from a lamp post"],"answer":0,"evidence":"Last, hang your feeder from a tree branch."},{"type":"author","q":"What is the main purpose of this text?","options":["to tell a story about a pinecone","to tell how to make a bird feeder","to tell why birds fly in winter"],"answer":1}],"grade":2,"words":151,"auto":{"fk":2.2,"decodable":null,"checks":"pass"}},{"id":"g2-u3-c02","unit":"G2-U3","pool":"check","title":"How to Make Fruit Salad","genre":"informational","source":"app-original","license":"app-original","text":"Fruit salad is a sweet and healthy snack. It is fun to make with a grown-up.\n\nYou will need a big bowl, a spoon, a banana, a cup of grapes, an apple and a handful of strawberries.\n\nStep 1: Wash your hands. Then wash the grapes, the apple and the strawberries. This rinses off dirt.\n\nStep 2: Peel the banana. Ask your grown-up to cut it into slices.\n\nStep 3: Have your grown-up cut the apple and strawberries into small pieces. Knives are sharp, so a grown-up should always do the cutting.\n\nStep 4: Put all the fruit into the bowl.\n\nStep 5: Gently mix the fruit with the spoon. Go slowly so the banana does not get squished.\n\nStep 6: Scoop the fruit salad into small cups and share it!\n\nTip: Squeeze a little lemon juice on top. It keeps the apple and banana from turning brown.","caption":"Safety: a grown-up does all the cutting.","questions":[{"type":"sequence","q":"What is the first step?","options":["Peel the banana.","Mix the fruit.","Wash your hands."],"answer":2,"evidence":"Step 1: Wash your hands."},{"type":"why","q":"Why should a grown-up do the cutting?","options":["Knives are sharp.","Kids do not like fruit.","It makes the fruit sweet."],"answer":0},{"type":"literal","q":"Why should you mix slowly?","options":["so the bowl does not get dirty","so the banana does not get squished","so the grapes stay very cold"],"answer":1,"evidence":"Go slowly so the banana does not get squished."},{"type":"evidence","q":"Which sentence tells why you might add lemon juice?","options":["Go slowly so the banana does not get squished.","Fruit salad is a sweet and healthy snack.","It keeps the apple and banana from turning brown."],"answer":2,"evidence":"It keeps the apple and banana from turning brown."},{"type":"feature","q":"What does the \"Tip\" part give you?","options":["an extra idea to try","the list of fruit","the very first step"],"answer":0}],"grade":2,"words":152,"auto":{"fk":2.1,"decodable":null,"checks":"pass"}},{"id":"g2-u3-c03","unit":"G2-U3","pool":"check","title":"How to Make a Pop-Up Card","genre":"informational","source":"app-original","license":"app-original","text":"A pop-up card is a fun way to say hello or thank you. When your friend opens it, a picture pops up!\n\nYou will need two sheets of paper, safe scissors, glue, and crayons or markers.\n\nFirst, fold one sheet of paper in half. This will be the inside of the card.\n\nNext, make two short cuts in the middle of the fold, side by side. Each cut should be as long as your thumb.\n\nThen open the paper. Push the strip between the cuts in, so it sticks out the other way. Close the card and press it flat. When you open it again, the strip will pop out like a little step.\n\nAfter that, draw a picture on the other sheet of paper, such as a cat, a cake or a star. Cut it out. Glue it to the front of the step.\n\nLast, fold the second sheet in half and glue it around the outside. Now write a kind note to your friend!","caption":"You will need: 2 sheets of paper, safe scissors, glue, crayons","questions":[{"type":"sequence","q":"What do you do first?","options":["Write a kind note inside.","Fold one sheet in half.","Draw a picture on paper."],"answer":1,"evidence":"First, fold one sheet of paper in half."},{"type":"literal","q":"How long should each cut be?","options":["as long as your arm","as long as the paper","as long as your thumb"],"answer":2,"evidence":"Each cut should be as long as your thumb."},{"type":"sequence","q":"What do you do right after you draw the picture?","options":["Cut it out.","Fold it up.","Write a note."],"answer":0,"evidence":"Cut it out."},{"type":"why","q":"Why do you push the strip in?","options":["so the glue can dry fast","so it pops out like a step","so the card stays shut tight"],"answer":1},{"type":"author","q":"What is the main purpose of this text?","options":["to tell a story about friends","to list kinds of paper","to show how to make a card"],"answer":2}],"grade":2,"words":167,"auto":{"fk":2,"decodable":null,"checks":"pass"}},{"id":"g2-u3-c04","unit":"G2-U3","pool":"check","title":"How to Make Fruit Ice Pops","genre":"informational","source":"app-original","license":"app-original","text":"On a hot summer day, a cold ice pop is a great treat. You can make your own with fruit juice!\n\nYou will need small paper cups, fruit juice, wooden craft sticks and a little foil.\n\nFirst, pour juice into each cup. Fill the cups about three quarters of the way up. Do not fill them to the top, because juice gets bigger when it freezes.\n\nNext, cover each cup with a small piece of foil.\n\nThen poke a craft stick through the middle of the foil. The foil holds the stick up straight, so it does not tip over.\n\nAfter that, put the cups in the freezer. Leave them there for about five hours, or until they are frozen hard.\n\nLast, take out the cups. Peel off the foil and the paper cup. Hold the stick and enjoy!\n\nTry mixing two juices, like orange and grape, to make a brand new flavor.","caption":"You will need: paper cups, juice, craft sticks, foil","questions":[{"type":"why","q":"Why should you leave space at the top of the cup?","options":["Juice gets bigger when it freezes.","The stick needs room to wiggle.","The foil will melt if it is wet."],"answer":0},{"type":"sequence","q":"What do you do right after you cover the cups?","options":["Peel off the cup and the foil.","Poke a stick through the foil.","Pour juice into all the cups."],"answer":1,"evidence":"Then poke a craft stick through the middle of the foil."},{"type":"literal","q":"How long do the pops stay in the freezer?","options":["about five minutes","about five days","about five hours"],"answer":2,"evidence":"Leave them there for about five hours, or until they are frozen hard."},{"type":"evidence","q":"Which sentence tells what the foil does?","options":["The foil holds the stick up straight, so it does not tip over.","Do not fill them to the top, because juice gets bigger when it freezes.","Next, cover each cup with a small piece of foil."],"answer":0,"evidence":"The foil holds the stick up straight, so it does not tip over."},{"type":"main","q":"What is this text mostly about?","options":["how a freezer works","making ice pops from juice","keeping cool in the summer"],"answer":1}],"grade":2,"words":153,"auto":{"fk":1.9,"decodable":null,"checks":"pass"}},{"id":"g2-u4-p01","unit":"G2-U4","pool":"practice","title":"Frogs and Tadpoles","genre":"informational","source":"app-original","license":"app-original","text":"## Text 1: How a Frog Grows\n\nA frog starts life as a tiny egg in a pond. Frogs lay their eggs in big, jelly clumps. After a few days, each egg hatches into a tadpole. A tadpole has a long tail and no legs. It swims like a fish and breathes with gills. Slowly, the tadpole grows back legs. Then it grows front legs. Its tail gets shorter and shorter. At last, it is a small frog. It can hop out of the water and breathe air.\n\n## Text 2: Maya's Tadpole Journal\n\nMonday: Today our class got a tank with tadpoles in it. They look like little black commas with tails.\n\nWednesday: The tadpoles wiggle all day. I fed them some boiled lettuce.\n\nNext Monday: One tadpole has two tiny back legs! I named him Hopper.\n\nTwo weeks later: Hopper has four legs now, and his tail is almost gone. Tomorrow we will let him go at the pond.","questions":[{"type":"compare","q":"How are the two texts alike?","options":["Both tell about a class pet fish.","Both tell how a tadpole changes.","Both tell what frogs like to eat."],"answer":1},{"type":"compare","q":"How is Text 2 different from Text 1?","options":["It tells how frogs lay eggs in jelly.","It tells how tadpoles breathe with gills.","It tells about one tadpole a girl saw."],"answer":2},{"type":"literal","q":"What does a tadpole breathe with?","options":["gills","lungs","its tail"],"answer":0,"evidence":"It swims like a fish and breathes with gills."},{"type":"literal","q":"What did Hopper grow first?","options":["a long tail","two back legs","two front legs"],"answer":1,"evidence":"Next Monday: One tadpole has two tiny back legs!"}],"grade":2,"words":159,"auto":{"fk":2.5,"decodable":null,"checks":"pass"}},{"id":"g2-u4-p02","unit":"G2-U4","pool":"practice","title":"All About Snow","genre":"informational","source":"app-original","license":"app-original","text":"## Text 1: How Snow Forms\n\nSnow starts high up in the clouds. When the air is very cold, tiny drops of water freeze. They turn into small bits of ice called crystals. The crystals stick together and grow into snowflakes. When the snowflakes get heavy, they fall to the ground. Most snowflakes have six sides or six points. It is very rare for two snowflakes to look just the same.\n\n## Text 2: A Snow Day\n\nWhen Jada woke up, the yard was white. \"Snow day!\" she yelled. She put on her boots, her hat and her mittens.\n\nOutside, big flakes drifted down. Jada caught one on her black mitten. She looked at it up close. It had six tiny points, like a star!\n\nThen she and her brother built a snowman with a carrot nose. When they came inside, Mom made hot cocoa.","questions":[{"type":"compare","q":"What do both texts tell about snowflakes?","options":["They have six points.","They make snowmen.","They melt in cocoa."],"answer":0},{"type":"compare","q":"Which text tells how snow is made?","options":["both texts","Text 1","Text 2"],"answer":1},{"type":"literal","q":"What do tiny drops of water turn into?","options":["big drops of rain","soft puffy clouds","small bits of ice"],"answer":2,"evidence":"They turn into small bits of ice called crystals."},{"type":"inference","q":"How did Jada feel about the snow?","options":["excited","scared","bored"],"answer":0}],"grade":2,"words":143,"auto":{"fk":1.5,"decodable":null,"checks":"pass"}},{"id":"g2-u4-c01","unit":"G2-U4","pool":"check","title":"Bees at Work","genre":"informational","source":"app-original","license":"app-original","text":"## Text 1: Why Bees Matter\n\nBees are small, but they do a big job. When a bee visits a flower, yellow dust called pollen sticks to its fuzzy body. The bee carries the pollen to the next flower. This helps the plants make fruit and seeds. Many foods we eat, like apples, berries and pumpkins, need bees. Without bees, we would have much less food.\n\n## Text 2: A Visit to a Beekeeper\n\nLast summer, Noah visited his aunt Kim. She keeps bees in white wooden boxes called hives. Aunt Kim gave Noah a suit with a net over his face, so he would not get stung. She lifted a frame out of the hive. It was covered with bees and golden honey.\n\n\"The bees made all of this from flowers,\" she said.\n\nNoah tasted the honey. It was the sweetest thing he ever ate.","questions":[{"type":"compare","q":"What do both texts tell about bees?","options":["They help apples grow.","They visit flowers.","They live in boxes."],"answer":1},{"type":"compare","q":"How is Text 2 different from Text 1?","options":["It tells how bees carry pollen.","It lists foods that need bees.","It tells about one boy's visit."],"answer":2},{"type":"literal","q":"What sticks to a bee's body?","options":["pollen","honey","water"],"answer":0,"evidence":"When a bee visits a flower, yellow dust called pollen sticks to its fuzzy body."},{"type":"why","q":"Why did Noah wear a suit with a net?","options":["so he would stay very warm","so he would not get stung","so he could see the bees"],"answer":1},{"type":"evidence","q":"Which sentence best shows that bees help us get food?","options":["Aunt Kim gave Noah a suit with a net over his face, so he would not get stung.","She keeps bees in white wooden boxes called hives.","Many foods we eat, like apples, berries and pumpkins, need bees."],"answer":2,"evidence":"Many foods we eat, like apples, berries and pumpkins, need bees."}],"grade":2,"words":144,"auto":{"fk":2.4,"decodable":null,"checks":"pass"}},{"id":"g2-u4-c02","unit":"G2-U4","pool":"check","title":"Owls in the Dark","genre":"informational","source":"app-original","license":"app-original","text":"## Text 1: Owls at Night\n\nMost owls hunt at night. They have big eyes that help them see in the dark. An owl cannot move its eyes, so it turns its whole head instead. It can turn its head almost all the way around! Owls also have soft, fluffy feathers. These feathers help them fly with almost no sound. That way, mice do not hear them coming.\n\n## Text 2: The Owl at Camp\n\nLucas and his mom were camping in the woods. When it got dark, they sat by the campfire. Then Lucas heard a sound. \"Hoo, hoo-hoo.\"\n\n\"That is a great horned owl,\" Mom said softly. She pointed her flashlight up at a tall pine tree. Two big yellow eyes looked down at them.\n\nThen the owl spread its wings and flew away. Lucas listened, but he never heard a single flap.","questions":[{"type":"compare","q":"What do both texts show about owls?","options":["They fly with almost no sound.","They sleep in tents at camp.","They eat berries in the woods."],"answer":0},{"type":"compare","q":"Which text tells a story about a family trip?","options":["both texts","Text 2","Text 1"],"answer":1},{"type":"literal","q":"Why does an owl turn its whole head?","options":["Its neck is very long.","It wants to look silly.","It cannot move its eyes."],"answer":2,"evidence":"An owl cannot move its eyes, so it turns its whole head instead."},{"type":"literal","q":"Where was the owl in Text 2?","options":["in a tall pine tree","on top of the tent","next to the campfire"],"answer":0,"evidence":"She pointed her flashlight up at a tall pine tree."},{"type":"inference","q":"How did Lucas most likely feel when he saw the owl?","options":["sleepy","amazed","angry"],"answer":1}],"grade":2,"words":144,"auto":{"fk":1.7,"decodable":null,"checks":"pass"}},{"id":"g2-u4-c03","unit":"G2-U4","pool":"check","title":"Looking at the Moon","genre":"informational","source":"app-original","license":"app-original","text":"## Text 1: Facts About the Moon\n\nThe Moon is our closest neighbor in space. It is a big ball of rock with no air to breathe. The Moon does not make its own light. It shines because sunlight bounces off it. The Moon is covered with big holes called craters. In 1969, two astronauts became the first people to walk on the Moon. Their footprints are still there today, because there is no wind to blow them away.\n\n## Text 2: Moon Watching\n\nEvery night this month, Priya looked at the Moon from her window. On the first night, it was a thin, curved line, like a smile. Each night, it got a little bigger. After about two weeks, it was a full, round circle. It was so bright that it lit up her room.\n\n\"The Moon looks like it changes,\" said Priya's grandma. \"But really, we just see more or less of its sunny side.\"","questions":[{"type":"compare","q":"How are the two texts different?","options":["Text 1 tells a story, and Text 2 gives facts.","Text 1 and Text 2 are both poems about stars.","Text 1 gives facts, and Text 2 tells a story."],"answer":2},{"type":"compare","q":"What do both texts tell about the Moon?","options":["It shines with light from the Sun.","It has footprints from astronauts.","It is covered with deep craters."],"answer":0},{"type":"literal","q":"Why are the footprints still on the Moon?","options":["The Moon is too cold for them to fade.","There is no wind to blow them away.","Astronauts painted them on the rock."],"answer":1,"evidence":"Their footprints are still there today, because there is no wind to blow them away."},{"type":"literal","q":"How did the Moon look on the first night?","options":["like a full, round circle","like a big, dark hole","like a thin, curved smile"],"answer":2,"evidence":"On the first night, it was a thin, curved line, like a smile."},{"type":"vocab","q":"In Text 1, what are craters?","options":["big holes on the Moon","tall hills of sand","bright stars in space"],"answer":0,"evidence":"The Moon is covered with big holes called craters."}],"grade":2,"words":155,"auto":{"fk":2.7,"decodable":null,"checks":"pass"}},{"id":"g2-u4-c04","unit":"G2-U4","pool":"check","title":"Two Kinds of Bears","genre":"informational","source":"app-original","license":"app-original","text":"## Text 1: Polar Bears\n\nPolar bears live in the far north, where it is icy and cold. They have thick white fur and a layer of blubber to keep them warm. Their white fur helps them hide in the snow. Polar bears are strong swimmers. They hunt for seals on the sea ice. A polar bear's paws are about as wide as a dinner plate. This helps it walk on snow and ice.\n\n## Text 2: Giant Pandas\n\nGiant pandas live in the mountains of China. They have black and white fur. Pandas eat bamboo, a tall, tough kind of grass. A panda can spend about half of its day eating! Pandas have a special bump on each front paw that works like a thumb. It helps them hold the bamboo stalks. Pandas are good climbers, and they often rest in trees.","questions":[{"type":"compare","q":"How are the two texts alike?","options":["Both tell how to care for a pet.","Both give facts about a kind of bear.","Both tell a story about a lost bear."],"answer":1},{"type":"compare","q":"How are polar bears and pandas alike?","options":["They eat lots of bamboo.","They hunt seals on ice.","They have helpful paws."],"answer":2},{"type":"literal","q":"Which bear eats bamboo?","options":["the panda","the polar bear","both bears"],"answer":0,"evidence":"Pandas eat bamboo, a tall, tough kind of grass."},{"type":"why","q":"Why is white fur good for a polar bear?","options":["It helps the bear eat bamboo.","It helps the bear hide in snow.","It helps the bear climb trees."],"answer":1},{"type":"evidence","q":"Which sentence best shows how pandas use their paws?","options":["This helps it walk on snow and ice.","They have black and white fur.","It helps them hold the bamboo stalks."],"answer":2,"evidence":"It helps them hold the bamboo stalks."}],"grade":2,"words":141,"auto":{"fk":2,"decodable":null,"checks":"pass"}},{"id":"g2-u5-p01","unit":"G2-U5","pool":"practice","title":"Ben's Helpful Day","genre":"narrative","source":"app-original","license":"app-original","text":"Ben wanted to be helpful all day long.\n\nIn the morning, he helped Dad unpack the bags from the store. He put the apples in a bowl and the milk in the fridge.\n\nThen Ben saw that his little sister's shoe was untied. He bent down and retied it with a double knot.\n\nAt lunch, Grandma's cup was empty. Ben refilled it with cold water.\n\nAfter lunch, Ben ran to the yard to play. He was careless and left the gate open. Oh no! Biscuit ran out!\n\nBen felt unhappy. He ran down the street and called, \"Biscuit, come back!\" The puppy came running. Ben shut the gate and checked it twice.\n\nThat night, Dad said, \"Thank you for all your help today.\" Ben smiled. Being helpful felt great, and next time he would be more careful with the gate.","questions":[{"type":"vocab","q":"In the story, what does unpack mean?","options":["put things in","pack up again","take things out"],"answer":2,"evidence":"In the morning, he helped Dad unpack the bags from the store."},{"type":"vocab","q":"What does refilled mean?","options":["filled again","left empty","filled with care"],"answer":0,"evidence":"Ben refilled it with cold water."},{"type":"literal","q":"What happened when Ben left the gate open?","options":["The milk spilled.","Biscuit ran out.","Grandma fell asleep."],"answer":1,"evidence":"Biscuit ran out!"},{"type":"theme","q":"What did Ben learn?","options":["to stay inside all day","to unpack bags faster","to be more careful"],"answer":2}],"grade":2,"words":140,"auto":{"fk":1.5,"decodable":null,"checks":"pass"}},{"id":"g2-u5-p02","unit":"G2-U5","pool":"practice","title":"Mia's Sunflowers","genre":"narrative","source":"app-original","license":"app-original","text":"Mia planted sunflower seeds in a long row. Each day she watered them. She was hopeful that they would grow tall.\n\nOne windy night, a storm came. In the morning, Mia ran outside. Some of the little plants were bent and broken. Mia was unhappy. \"My garden is ruined,\" she said.\n\nHer neighbor, Mister Diaz, came over. \"Do not be hopeless,\" he said. \"We can fix this.\"\n\nThey pulled out the broken plants. Then they replanted the row with new seeds. Mister Diaz showed Mia how to tie the strong plants to sticks, so the wind could not knock them down.\n\nMia was careful with her garden all summer. In August, the sunflowers were taller than Mister Diaz! Mia was thankful for his help. She gave him the biggest flower.","questions":[{"type":"vocab","q":"What does hopeful mean?","options":["hoping again","full of hope","without hope"],"answer":1,"evidence":"She was hopeful that they would grow tall."},{"type":"vocab","q":"In the story, what does replanted mean?","options":["never planted","planted with care","planted again"],"answer":2,"evidence":"Then they replanted the row with new seeds."},{"type":"why","q":"Why did they tie the plants to sticks?","options":["so the wind could not knock them down","so the plants would get more water","so birds could sit on top of them"],"answer":0},{"type":"literal","q":"How tall were the sunflowers in August?","options":["as tall as a paper cup","taller than Mister Diaz","as small as a little seed"],"answer":1,"evidence":"In August, the sunflowers were taller than Mister Diaz!"}],"grade":2,"words":130,"auto":{"fk":2,"decodable":null,"checks":"pass"}},{"id":"g2-u5-c01","unit":"G2-U5","pool":"check","title":"Leo's Unlucky Morning","genre":"narrative","source":"app-original","license":"app-original","text":"Leo woke up late. His alarm clock was unplugged! He jumped out of bed in a hurry.\n\nHe was in such a rush that he was careless. He put his shirt on backward. He had to take it off and redo it. Then he spilled his cereal. He had to refill his bowl.\n\nAt the bus stop, Leo saw that his backpack was unzipped. His homework was gone! He was unhappy. It felt like the most unlucky day ever.\n\nThen his friend Sara ran up. She was holding a paper. \"Is this yours?\" she asked. \"It was on the sidewalk.\"\n\nIt was Leo's homework! \"Thank you!\" said Leo. \"You are so helpful.\"\n\n\"That is what friends are for,\" said Sara.\n\nLeo zipped up his backpack and smiled. Maybe the day was not so unlucky after all.","questions":[{"type":"vocab","q":"In the story, what does unplugged mean?","options":["plugged in again","full of plugs","not plugged in"],"answer":2,"evidence":"His alarm clock was unplugged!"},{"type":"vocab","q":"What does refill mean?","options":["fill again","make empty","fill with care"],"answer":0,"evidence":"He had to refill his bowl."},{"type":"literal","q":"What did Leo see at the bus stop?","options":["The bus was running late.","His backpack was unzipped.","His shoes were both untied."],"answer":1,"evidence":"At the bus stop, Leo saw that his backpack was unzipped."},{"type":"why","q":"Why did Leo think it was an unlucky day?","options":["He had no friends at all.","It was raining very hard.","Many things went wrong."],"answer":2},{"type":"inference","q":"How did Leo feel at the end?","options":["happy and thankful","sad and upset","tired and grumpy"],"answer":0}],"grade":2,"words":136,"auto":{"fk":1.1,"decodable":null,"checks":"pass"}},{"id":"g2-u5-c02","unit":"G2-U5","pool":"check","title":"Reuse and Refill","genre":"informational","source":"app-original","license":"app-original","text":"Every day, people throw away lots of trash. Much of it is plastic. Plastic can last for hundreds of years. But there are easy ways to make less trash.\n\nOne way is to reuse things. To reuse means to use something again. You can reuse a glass jar to hold pencils or buttons. You can reuse a shoe box to store toys.\n\nAnother way is to refill things. You do not need a new bottle of water each day. You can refill the same bottle again and again. This is a useful habit, and it saves money too.\n\nSome things seem useless, like an empty cereal box. But they do not have to be trash. You can recycle them, so they can be made into something new.\n\nWhen you are careful about what you throw away, you are helpful to the Earth. Small steps make a big difference!","questions":[{"type":"vocab","q":"In the text, what does reuse mean?","options":["use a lot","use again","throw out"],"answer":1,"evidence":"To reuse means to use something again."},{"type":"literal","q":"What can a glass jar hold?","options":["shoes or boots","water for plants","pencils or buttons"],"answer":2,"evidence":"You can reuse a glass jar to hold pencils or buttons."},{"type":"vocab","q":"What does useful mean in this text?","options":["helpful","broken","empty"],"answer":0,"evidence":"This is a useful habit, and it saves money too."},{"type":"main","q":"What is this text mostly about?","options":["why jars are made of glass","ways to make less trash","how plastic is made"],"answer":1},{"type":"author","q":"Why did the author write this?","options":["to tell a funny story about a jar","to teach how to build a box","to get people to make less trash"],"answer":2}],"grade":2,"words":148,"auto":{"fk":3,"decodable":null,"checks":"pass"}},{"id":"g2-u5-c03","unit":"G2-U5","pool":"check","title":"The Block Tower","genre":"narrative","source":"app-original","license":"app-original","text":"Ana and Jin wanted to build the tallest block tower in the class. They stacked the blocks fast. The tower was unsteady. It wobbled, and then it fell down with a crash!\n\n\"That was useless,\" said Jin. He felt hopeless.\n\n\"Let's rebuild it,\" said Ana. \"But this time, let's be careful.\"\n\nThey made a wide, flat bottom with the biggest blocks. Then they put smaller blocks on top. They worked slowly. When a block was crooked, they took it off and reset it.\n\nThe new tower was taller than Jin! It did not wobble at all. Their teacher, Miss Hall, took a picture of it.\n\n\"I am thankful you did not give up,\" Jin told Ana.\n\n\"Me too,\" said Ana. \"Being careful made our tower strong.\"","questions":[{"type":"vocab","q":"What does unsteady mean in the story?","options":["wobbly","strong","tall"],"answer":0,"evidence":"The tower was unsteady."},{"type":"vocab","q":"What does rebuild mean?","options":["knock down","build again","build fast"],"answer":1,"evidence":"\"Let's rebuild it,\" said Ana."},{"type":"sequence","q":"What did they make first the second time?","options":["the smallest blocks","a tall, thin top","a wide, flat bottom"],"answer":2,"evidence":"They made a wide, flat bottom with the biggest blocks."},{"type":"why","q":"Why did the new tower stand up?","options":["They built it with care.","They glued it all together.","Miss Hall held it up."],"answer":0},{"type":"theme","q":"What lesson do Ana and Jin learn?","options":["Blocks are useless for building.","Being careful and trying again helps.","Building fast makes strong towers."],"answer":1}],"grade":2,"words":126,"auto":{"fk":1.4,"decodable":null,"checks":"pass"}},{"id":"g2-u5-c04","unit":"G2-U5","pool":"check","title":"The Thankful Jar","genre":"narrative","source":"app-original","license":"app-original","text":"Grandma Rose has a jar on her kitchen table. She calls it her thankful jar. Every night, she writes one thing she is thankful for on a slip of paper. Then she drops it in the jar.\n\nWhen Nia came to stay for a week, Grandma gave her a pencil and some paper. \"You can add to the jar too,\" she said.\n\nOn the first night, Nia missed her home, and she was unhappy. She could not think of anything to write. Grandma said, \"Think of one small, good thing.\" Nia wrote, \"I am thankful for Grandma's warm blankets.\"\n\nEach day after that, Nia noticed more good things. She was thankful for the friendly cat next door. She was thankful for pancakes and for a sunny walk in the park.\n\nOn the last night, Nia reread all of her notes. She felt joyful. \"I will make a thankful jar at home,\" she said.","questions":[{"type":"vocab","q":"In the story, what does thankful mean?","options":["full of thanks","without thanks","thanking again"],"answer":0,"evidence":"She calls it her thankful jar."},{"type":"vocab","q":"What does reread mean?","options":["read fast","read again","never read"],"answer":1,"evidence":"On the last night, Nia reread all of her notes."},{"type":"literal","q":"What does Grandma write on each night?","options":["a big gray rock","the kitchen wall","a slip of paper"],"answer":2,"evidence":"Every night, she writes one thing she is thankful for on a slip of paper."},{"type":"why","q":"Why was Nia unhappy on the first night?","options":["She missed her home.","She lost her pencil.","The cat ran away."],"answer":0},{"type":"inference","q":"How did Nia change by the end?","options":["She wanted to go home.","She saw more good things.","She stopped writing notes."],"answer":1}],"grade":2,"words":153,"auto":{"fk":2.2,"decodable":null,"checks":"pass"}},{"id":"oral-g2-01","pool":"oral-g2","title":"The Big Red Kite","genre":"narrative","source":"app-original","license":"app-original","text":"Jack and his sister Pam had a big red kite. It had a long tail with yellow bows.\n\nOne windy Saturday, they went up the grassy hill behind their house. Jack held the string. Pam held the kite up high above her head.\n\n\"Run!\" said Pam. Jack ran as fast as he could. The wind lifted the kite up, up, up. It went higher than the trees. Soon it looked like a red dot in the sky.\n\nThen the wind stopped. The kite started to drop! Jack pulled on the string, and the kite went back up.\n\nThey flew the kite together until it was time for dinner. Then they rolled up the string and walked happily back home.","questions":[],"grade":2,"words":119,"auto":{"fk":0.6,"decodable":0.99,"checks":"pass"}},{"id":"oral-g2-02","pool":"oral-g2","title":"Pet Day","genre":"narrative","source":"app-original","license":"app-original","text":"Friday was Pet Day at school. Every kid could bring a pet or a picture of a pet.\n\nNora brought her rabbit, Clover. He had soft white fur and long pink ears. Max brought a fish in a plastic tank. It was orange and gold. Lin did not have a pet, so she made a drawing of a tiger.\n\n\"A tiger is not a pet!\" said Max with a grin.\n\n\"It is my pretend pet,\" said Lin. \"His name is Stripes, and he likes pancakes.\"\n\nThe whole class giggled. Then each kid told one fun fact about a pet. It was the best Friday ever.","questions":[],"grade":2,"words":105,"auto":{"fk":1.2,"decodable":0.97,"checks":"pass"}},{"id":"oral-g2-03","pool":"oral-g2","title":"The Snowman Contest","genre":"narrative","source":"app-original","license":"app-original","text":"It snowed all night. In the morning, the park was white and sparkly. It was time for the snowman contest!\n\nOmar and his dad rolled three big balls of snow. They put the biggest one on the bottom and the smallest one on top. Omar used two black stones for eyes and a carrot for a nose. Dad gave the snowman his old green scarf.\n\nNext to them, Hana made a snow cat with long whiskers. Her sister made a snow dragon with a curly tail.\n\nAt noon, the judges came. They gave prizes to everyone. Omar got the prize for the tallest snowman. He was so happy!","questions":[],"grade":2,"words":108,"auto":{"fk":2,"decodable":1,"checks":"pass"}},{"id":"oral-g2-04","pool":"oral-g2","title":"Rain on the Farm","genre":"narrative","source":"app-original","license":"app-original","text":"Farmer Jen looked up at the sky. Dark clouds were rolling in. \"Rain is coming,\" she said.\n\nThe corn in the fields was dry and thirsty. The water in the pond was very low. The ducks waited together at the muddy edge.\n\nThen, plip, plop, the rain began. It fell on the barn and on the fields. It filled up the pond. The ducks splashed and quacked.\n\nJen put on her yellow rubber boots and hurried out to the vegetable garden. She jumped in a big puddle. Splash! Her dog, Rusty, jumped in too.\n\nThe next day, the corn stood tall and green. \"Thank you, rain,\" said Jen with a smile.","questions":[],"grade":2,"words":111,"auto":{"fk":1,"decodable":1,"checks":"pass"}}];
